// Generated by OrchestKit Claude Plugin
// Created: 2026-08-01

/**
 * Multi-Step Task Nudge — UserPromptSubmit sub-hook (prompt/unified-dispatcher)
 *
 * CLAUDE.md says "Use TaskCreate for 3+ step work" and nothing enforces it —
 * the one hook written for the job (pretool/task/task-existence-gate) was never
 * registered, and even wired it would not help: it matches agent spawns inside
 * active pipelines and exempts every agent type ordinary sessions use. The
 * observable result is coin-flip task usage across sessions (operator
 * complaint, 2026-08-01: ~7 harness reminders in one session, a different
 * judgement call each time).
 *
 * This sub-hook closes the loop the supported way (verified against the CC
 * hooks docs, 2026-08-01):
 *
 *   prompt lands ──▶ 3+ step shape AND session has no tasks yet?
 *                        └─ yes ─▶ advisory context (never blocks)
 *   TaskCreate happens ─▶ TaskCreated event (CC-native, 2.1.84) logs the
 *                        session_id ─▶ this hook goes PERMANENTLY SILENT
 *                        for the session
 *   Stop ──▶ task-completion-check records qualifying-work-vs-task-usage
 *            telemetry, so the gap is measurable instead of anecdotal
 *
 * Deliberately advisory. A blocking gate here would fight the harness and
 * train `--no-verify` reflexes; the precedent (visual-style-nudge, same
 * dispatcher) shows a throttled advisory re-anchor works on a real operator.
 *
 * Runs inside prompt/unified-dispatcher — no hooks.json entry, no entries-map
 * edit, so there is no #959 dead-hook surface to forget. Zero resident tokens;
 * cost is per-turn only when it fires, inside the dispatcher's existing cap.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import type { HookContext, HookInput, HookResult } from '../types.js';
import { outputPromptContext, outputSilentSuccess } from '../lib/common.js';
import { NOOP_CTX } from '../lib/context.js';
import { getSessionStorageDir } from '../lib/paths.js';
import { safeIdentifier } from '../lib/safe-fs.js';
import { sessionHasTasks } from '../lib/task-usage-signal.js';

const HOOK_NAME = 'multi-step-task-nudge';

/** Below this the prompt is a command or an answer, not a work request. */
const MIN_PROMPT_LENGTH = 40;

/** After the first nudge, re-fire only every Nth qualifying prompt. */
const THROTTLE_EVERY = 6;

/**
 * EXPLICIT ask: the operator is talking about task/todo organisation itself.
 * Never throttled — rate-limiting the literal request is how visual-style-nudge
 * measured 4 silenced explicit asks in one session before its bypass existed.
 */
const EXPLICIT_RE = /\b(?:todo list|task list|todos?\b|taskcreate|organi[sz]e (?:our|the|this) (?:session|work))/i;

/** A skill route manages its own task ceremony — never second-guess it. */
const ALREADY_ROUTED_RE = /\/(?:ork|hq-ext):[a-z-]+/i;

/** Imperative build-verbs. DISTINCT matches are counted, not occurrences. */
const VERB_RE =
  /\b(?:implement|build|fix|add|create|write|wire|migrate|refactor|rename|update|test|verify|ship|deploy|audit|sweep|extract|split|merge|document|measure|prove|remove|delete|rebuild)\b/gi;

/** Sequencing that turns a verb pile into an ordered plan. */
const SEQUENCE_RE = /\b(?:then|after that|first\b[\s\S]{0,80}?\bthen|and (?:then|also|finally))\b|;/i;

/** Numbered or bulleted list items. */
const LIST_ITEM_RE = /(?:^|\n)\s*(?:\d+[.)]|[-*•])\s+\S/g;

/**
 * Does this prompt read as 3+ step work? Precision over recall: every miss
 * costs nothing (the harness reminder still exists), every false fire costs
 * operator trust in the nudge.
 */
export function isMultiStepShaped(prompt: string): boolean {
  const listItems = prompt.match(LIST_ITEM_RE)?.length ?? 0;
  if (listItems >= 2) return true;

  const verbs = new Set(
    (prompt.match(VERB_RE) ?? []).map((v) => v.toLowerCase()),
  );
  if (verbs.size >= 3) return true;
  if (verbs.size >= 2 && SEQUENCE_RE.test(prompt)) return true;

  return false;
}

function counterPath(sessionId: string): string {
  // session_id is untrusted hook input (#1826 class): sanitize before it
  // becomes a filename, so a '../' segment cannot escape the session dir.
  const safe = safeIdentifier(sessionId, 'invalid');
  return join(getSessionStorageDir(), `${safe}-task-nudge.count`);
}

/**
 * 1-based fire ordinal for this qualifying prompt, or null to stay quiet.
 * Fails CLOSED as null — a counter problem must never become per-turn noise.
 * The counter doubles as the Stop-side "qualifying prompts seen" measurement.
 */
function fireOrdinal(sessionId: string, explicit: boolean): number | null {
  const path = counterPath(sessionId);
  let seen = 0;
  try {
    if (existsSync(path)) {
      const parsed = Number.parseInt(readFileSync(path, 'utf8').trim(), 10);
      if (Number.isFinite(parsed) && parsed >= 0) seen = parsed;
    }
  } catch {
    return null;
  }

  try {
    mkdirSync(getSessionStorageDir(), { recursive: true });
    writeFileSync(path, String(seen + 1), 'utf8');
  } catch {
    return null;
  }

  if (explicit) return seen + 1;
  if (seen % THROTTLE_EVERY !== 0) return null;
  return Math.floor(seen / THROTTLE_EVERY) + 1;
}

/** Exposed for the Stop-side measurement (task-completion-check). */
export function qualifyingPromptCount(sessionId: string): number {
  try {
    const path = counterPath(sessionId);
    if (!existsSync(path)) return 0;
    const parsed = Number.parseInt(readFileSync(path, 'utf8').trim(), 10);
    return Number.isFinite(parsed) && parsed >= 0 ? parsed : 0;
  } catch {
    return 0;
  }
}

export function multiStepTaskNudge(
  input: HookInput,
  ctx: HookContext = NOOP_CTX,
): HookResult {
  const prompt = typeof input.prompt === 'string' ? input.prompt : '';
  const sessionId = input.session_id || 'unknown-session';
  const projectDir = input.project_dir || process.env.CLAUDE_PROJECT_DIR || '';

  if (prompt.length < MIN_PROMPT_LENGTH) return outputSilentSuccess();
  if (ALREADY_ROUTED_RE.test(prompt)) return outputSilentSuccess();

  const explicit = EXPLICIT_RE.test(prompt);
  if (!explicit && !isMultiStepShaped(prompt)) return outputSilentSuccess();

  // The permanent silencer: once this session has ANY task, the nudge's job is
  // done. Checked AFTER shape detection so the tail-read runs only on the rare
  // qualifying prompt, and the counter still advances first — the Stop-side
  // telemetry must count qualifying work even in sessions that used tasks.
  const ordinal = fireOrdinal(sessionId, explicit);
  if (sessionHasTasks(projectDir, sessionId)) return outputSilentSuccess();
  if (ordinal === null) return outputSilentSuccess();

  ctx.log(HOOK_NAME, `fired #${ordinal} (explicit=${explicit})`);

  // The ordinal is load-bearing: unified-dispatcher delta-detects consolidated
  // context and drops byte-identical turns, so a constant message would fire
  // exactly once per session and every later re-anchor would be swallowed.
  return outputPromptContext(
    `[task-nudge #${ordinal}] This prompt reads as 3+ step work and no task ` +
      `list exists yet this session. Open one now — TaskCreate per step, then ` +
      `TaskUpdate(status=in_progress/completed) as you go — so progress is ` +
      `visible and survives interruption. This nudge goes silent for the ` +
      `whole session after the first TaskCreate.`,
  );
}
